effect.shader:
void main(){
    vec2 uv = acScreenNorm*2.0 - 1.0;
    vec2 off = uv.yx*uv.yx * curve * 0.25;
    uv += uv*off;
    uv = uv*0.5 + 0.5;
    if(uv.x<0.0||uv.x>1.0||uv.y<0.0||uv.y>1.0){ gl_FragColor=vec4(0.0); return; }
    vec4 col = texture2DCv(inputImg.texture, uv);
    float sl = sin(uv.y*acScreenSize.y*1.0)*0.5+0.5;
    col.rgb *= 1.0 - sl*scanline*0.4;
    float ph = mod(floor(uv.x*acScreenSize.x), 3.0);
    vec3 mask = vec3(ph==0.0?1.0:0.7, ph==1.0?1.0:0.7, ph==2.0?1.0:0.7);
    col.rgb *= mix(vec3(1.0), mask, scanline*0.5);
    float v = length((acScreenNorm-0.5));
    col.rgb *= 1.0 - v*v*vignette*1.5;
    col.rgb *= bright;
    gl_FragColor = col;
}
